"""Corrections to discussion_source.txt after matching each citation to what its abstract supports."""
p = r'.\discussion_source.txt'
t = open(p, encoding='utf-8').read()
def rep(a, b):
    global t
    assert t.count(a) == 1, (t.count(a), a[:80]); t = t.replace(a, b)
rep("showed the highest proportional inundation <<10.1016/j.ecolind.2026.115591;10.1038/s41598-026-63431-0>>.", "showed the highest proportional inundation <<10.1016/j.ecolind.2026.115591>>.")
rep("identify vegetated and urban areas as the main remaining limitation <<10.3390/rs70607732;10.3390/rs16040656>>", "identify vegetated and urban areas as where severe limitations remain <<10.3390/rs70607732;10.3390/rs16040656>>")
rep("have been found to exceed the contrast produced by inundation <<10.3390/rs14153838;10.1016/j.rse.2022.113273>>.", "have been found to exceed the contrast produced by inundation, and not every land-cover change between dates is flood-induced <<10.3390/rs14153838;10.3390/rs14020246>>.")
rep("since mapping chains that work well elsewhere derive their thresholds from the local data and pair them with filters that remove likely false positives <<10.1016/j.rse.2022.113273;10.1016/j.rse.2025.115108>>.", "since established mapping chains typically derive their thresholds from the imagery itself and pair them with filters or context layers that flag likely false positives <<10.1016/j.rse.2022.113273;10.1016/j.rse.2025.115108>>.")
rep("Apparent accuracy depends on how common the mapped class is and on the quality of the reference, and kappa has been argued to be unsuitable for assessing and comparing thematic map accuracy <<10.1016/j.rse.2019.111630;10.1371/journal.pone.0291908>>.", "Apparent accuracy depends on how common the mapped class is and on the quality of the reference, and common metrics shift with both <<10.1371/journal.pone.0291908;10.3390/rs16040656>>.")
rep("Reviews of SAR flood mapping likewise call for quantitative metrics and high-quality reference data <<10.3390/rs16040656;10.1371/journal.pone.0291908>>.", "Reviews of SAR flood mapping likewise call for quantitative metrics and high-quality reference data <<10.3390/rs16040656>>.")
rep("because the response of backscatter to inundation depth differs between ground objects and is overlaid by non-flood variation <<10.3390/rs14153838;10.1016/j.ecolind.2026.115591>>.", "because the response of backscatter to inundation depth differs between ground objects and is overlaid by non-flood variation <<10.3390/rs14153838;10.3390/rs14020246>>. Ordinal severity classes built on the size of the backscatter reduction have precedent in floodplain indicator frameworks <<10.1016/j.ecolind.2026.115591>>.")
rep("Models trained on dual-polarised data have outperformed an operational rule-based chain <<10.1109/JSTARS.2022.3152127;10.1016/j.rse.2025.115108>>, and the optical polygons", "Models trained on dual-polarised data have outperformed an operational rule-based chain <<10.1109/JSTARS.2022.3152127>>, and the optical polygons")
rep("with interferometric coherence as the first added input for urban areas <<10.1109/TGRS.2022.3199036;10.1117/1.JRS.15.032003>>.", "with interferometric coherence or building-height information as candidate inputs for urban areas <<10.1109/TGRS.2022.3199036;10.1117/1.JRS.15.032003>>. A multi-date historical reference in place of two scenes would also reduce the dependence on the pre-event scene <<10.3390/rs14020246;10.1016/j.rse.2022.113273>>.")
open(p, 'w', encoding='utf-8', newline='').write(t); print('discussion text corrected')
